WHERE	f.USE_AT = 'Y'

AND		f.FAQ_CL_CODE = #{faqClCode}



AND		(f.QESTN_SJ LIKE #{searchPattern} OR f.ANSWER_CN LIKE #{searchPattern})

mapper.select:
SELECT FROM COMTNFAQINFO f
ORDER BY c.SORT_ORDR, f.SORT_ORDR, f.FAQ_ID
LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO COMTNFAQINFO
	   (FAQ_ID
	  , QESTN_SJ
	  , QESTN_CN
	  , ANSWER_CN
	  , RDCNT
	  , ATCH_FILE_ID
	  , FRST_REGIST_PNTTM
	  , FRST_REGISTER_ID
	  , LAST_UPDT_PNTTM
	  , LAST_UPDUSR_ID
	  , FAQ_CL_CODE
	  , SORT_ORDR
	  , USE_AT)
VALUES ( #{faqId}
	  , #{qestnSj}
	  , #{qestnCn}
	  , #{answerCn}
	  , 0
	  , NULL
	  , #{audit.now}
	  , #{audit.userId}
	  , #{audit.now}
	  , #{audit.userId}
	  , #{faqClCode}
	  , #{sortOrdr}
	  , 'Y' )

mapper.update:
			UPDATE	COMTNFAQINFO	SET
				    QESTN_SJ=#{qestnSj}
				  , ANSWER_CN=#{answerCn}
				  , FAQ_CL_CODE=#{faqClCode}
				  , SORT_ORDR=#{sortOrdr}
				  , LAST_UPDT_PNTTM=#{audit.now}
				  , LAST_UPDUSR_ID=#{audit.userId}
 			WHERE  FAQ_ID=#{faqId}
 			AND    USE_AT = 'Y'

UPDATE	COMTNFAQINFO	SET
	    USE_AT = 'N'
	  , LAST_UPDT_PNTTM=#{audit.now}
	  , LAST_UPDUSR_ID=#{audit.userId}
WHERE  FAQ_ID=#{faqId}
AND    USE_AT = 'Y'
